class Solution:
    def maximumGap(self, nums: List[int]) -> int:
        if len(nums) < 2:
            return 0
        min_val, max_val = min(nums), max(nums)
        if min_val == max_val:
            return 0
        n = len(nums)
        bucket_size = max(1, (max_val - min_val) // (n - 1))
        bucket_count = (max_val - min_val) // bucket_size + 1
        buckets = [[float("inf"), float("-inf")] for _ in range(bucket_count)]
        for x in nums:
            idx = (x - min_val) // bucket_size
            buckets[idx][0] = min(buckets[idx][0], x)
            buckets[idx][1] = max(buckets[idx][1], x)
        max_gap = 0
        prev_max = min_val
        for b_min, b_max in buckets:
            if b_min == float("inf"):
                continue
            max_gap = max(max_gap, b_min - prev_max)
            prev_max = b_max
        return max_gap

class Solution {
public:
    int maximumGap(vector<int>& nums) {
        int n = nums.size();
        if (n < 2) return 0;
        int minVal = *min_element(nums.begin(), nums.end());
        int maxVal = *max_element(nums.begin(), nums.end());
        if (minVal == maxVal) return 0;
        int bucketSize = max(1, (maxVal - minVal) / (n - 1));
        int bucketCount = (maxVal - minVal) / bucketSize + 1;
        vector<int> bMin(bucketCount, INT_MAX);
        vector<int> bMax(bucketCount, INT_MIN);
        for (int x : nums) {
            int idx = (x - minVal) / bucketSize;
            bMin[idx] = min(bMin[idx], x);
            bMax[idx] = max(bMax[idx], x);
        }
        int maxGap = 0;
        int prevMax = minVal;
        for (int i = 0; i < bucketCount; i++) {
            if (bMin[i] == INT_MAX) continue;
            maxGap = max(maxGap, bMin[i] - prevMax);
            prevMax = bMax[i];
        }
        return maxGap;
    }
};

class Solution {
    public int maximumGap(int[] nums) {
        int n = nums.length;
        if (n < 2) return 0;
        int minVal = nums[0], maxVal = nums[0];
        for (int x : nums) {
            minVal = Math.min(minVal, x);
            maxVal = Math.max(maxVal, x);
        }
        if (minVal == maxVal) return 0;
        int bucketSize = Math.max(1, (maxVal - minVal) / (n - 1));
        int bucketCount = (maxVal - minVal) / bucketSize + 1;
        int[] bMin = new int[bucketCount];
        int[] bMax = new int[bucketCount];
        Arrays.fill(bMin, Integer.MAX_VALUE);
        Arrays.fill(bMax, Integer.MIN_VALUE);
        for (int x : nums) {
            int idx = (x - minVal) / bucketSize;
            bMin[idx] = Math.min(bMin[idx], x);
            bMax[idx] = Math.max(bMax[idx], x);
        }
        int maxGap = 0;
        int prevMax = minVal;
        for (int i = 0; i < bucketCount; i++) {
            if (bMin[i] == Integer.MAX_VALUE) continue;
            maxGap = Math.max(maxGap, bMin[i] - prevMax);
            prevMax = bMax[i];
        }
        return maxGap;
    }
}

var maximumGap = function(nums) {
    const n = nums.length;
    if (n < 2) return 0;
    let minVal = nums[0], maxVal = nums[0];
    for (const x of nums) {
        minVal = Math.min(minVal, x);
        maxVal = Math.max(maxVal, x);
    }
    if (minVal === maxVal) return 0;
    const bucketSize = Math.max(1, Math.floor((maxVal - minVal) / (n - 1)));
    const bucketCount = Math.floor((maxVal - minVal) / bucketSize) + 1;
    const bMin = new Array(bucketCount).fill(Infinity);
    const bMax = new Array(bucketCount).fill(-Infinity);
    for (const x of nums) {
        const idx = Math.floor((x - minVal) / bucketSize);
        bMin[idx] = Math.min(bMin[idx], x);
        bMax[idx] = Math.max(bMax[idx], x);
    }
    let maxGap = 0;
    let prevMax = minVal;
    for (let i = 0; i < bucketCount; i++) {
        if (bMin[i] === Infinity) continue;
        maxGap = Math.max(maxGap, bMin[i] - prevMax);
        prevMax = bMax[i];
    }
    return maxGap;
};
